import unittest
from candidate import smallest_change

class TestSmallestChange(unittest.TestCase):
    def test_smallest_change_normalcase_expectedbehavior(self):
        self.assertEqual(smallest_change([1,2,3,5,4,7,9,6]), 4)

    def test_smallest_change_reverse_same_expectedbehavior(self):
        self.assertEqual(smallest_change([6,9,7,4,5,3,2,1]), 0)

    def test_smallest_change_mirrored_expectedbehavior(self):
        self.assertEqual(smallest_change([1,2,3,3,2,1]), 1)

    def test_smallest_change_odd_length_expectedbehavior(self):
        self.assertEqual(smallest_change([1,2,3,5]), 2)

    def test_smallest_change_even_length_one_mismatch_expectedbehavior(self):
        self.assertEqual(smallest_change([1,2,3,5,4]), 1)

    def test_smallest_change_empty_array(self):
        self.assertEqual(smallest_change([]), 0)

    def test_smallest_change_single_element(self):
        self.assertEqual(smallest_change([1]), 0)

    def test_smallest_change_only_one_pair_mismatch(self):
        self.assertEqual(smallest_change([1,2,2,3]), 1)

    def test_smallest_change_negative_numbers(self):
        self.assertEqual(smallest_change([-1,-2,-2,-3]), 1)

    def test_smallest_change_mixed_numbers(self):
        self.assertEqual(smallest_change([1,-2,3,-2]), 2)

    def test_smallest_change_floats(self):
        self.assertAlmostEqual(smallest_change([1.5,2.5,3.5,4.5]), 3)

    def test_smallest_change_type_errors(self):
        self.assertRaises(TypeError, smallest_change, [1, "2", 3])
        self.assertRaises(TypeError, smallest_change, [1, 2, None])
